// ACK correlation on the existing worker stdio channel. This is not an input
// queue and has no authority to inject keys. IDs are generated by Python.
const {performance} = require('node:perf_hooks');
function inputReceipts(send, wall=Date.now, mono=()=>performance.now(), limit=32) {
 const active=new Map();
 function begin(m) {
  if(m._receipt===undefined)return {valid:()=>true,wait:async p=>{await p;return true;},finish:()=>{}};
  const r=m._receipt, now=wall();
  if(!r||typeof r!=='object'||Object.keys(r).sort().join(',')!=='deadline_ms,generation,id'||
    typeof r.id!=='string'||!/^[0-9a-f]{32}$/.test(r.id)||!Number.isSafeInteger(r.generation)||r.generation<1||
    !Number.isFinite(r.deadline_ms)||r.deadline_ms<now||r.deadline_ms>now+2000||active.size>=limit||active.has(r.id))return null;
  const entry={...r,cancelled:false,started_ms:mono()};
  entry.aborted=new Promise(resolve=>entry.abort=resolve);active.set(r.id,entry);
  return {
   valid:()=>!entry.cancelled&&wall()<=entry.deadline_ms,
   async wait(promise){
    if(entry.cancelled||wall()>entry.deadline_ms)return false;
    let timer;
    try{return await Promise.race([Promise.resolve(promise).then(()=>true),entry.aborted,
     new Promise(resolve=>timer=setTimeout(()=>resolve(false),Math.max(0,entry.deadline_ms-wall())))]);}
    finally{clearTimeout(timer);}
   },
   finish(ok,level){
    if(active.get(r.id)!==entry)return;
    active.delete(r.id);entry.abort(false);
    const accepted=ok===true&&!entry.cancelled&&wall()<=entry.deadline_ms;
    send({type:'graphical-input-ack',id:r.id,generation:r.generation,ok:accepted,
     level:accepted?level:'Rejected',started_ms:entry.started_ms,finished_ms:mono()});
   }
  };
 }
 function cancel(m){
  const r=active.get(m.id);
  if(r&&r.generation===m.generation){r.cancelled=true;r.abort(false);}
 }
 function cancelAll(){for(const r of active.values()){r.cancelled=true;r.abort(false);}}
 return {begin,cancel,cancelAll};
}
module.exports={inputReceipts};
